CREATE TABLE "cadangan" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "cadangan_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"jenis" varchar(10) NOT NULL,
	"status" varchar(10) DEFAULT 'BERJALAN' NOT NULL,
	"pemicu" varchar(20) NOT NULL,
	"id_pengguna" bigint,
	"waktu_mulai" timestamp with time zone DEFAULT now() NOT NULL,
	"waktu_selesai" timestamp with time zone,
	"ukuran_dump" bigint,
	"snapshot_lokal" varchar(64),
	"status_lokal" varchar(10),
	"snapshot_cloud" varchar(64),
	"status_cloud" varchar(10),
	"pesan" varchar(1000),
	CONSTRAINT "chk_cadangan_jenis" CHECK (jenis in ('CADANGAN','UJI_PULIH')),
	CONSTRAINT "chk_cadangan_status" CHECK (status in ('BERJALAN','BERHASIL','GAGAL')),
	CONSTRAINT "chk_cadangan_pemicu" CHECK (pemicu in ('JADWAL','MANUAL','SEBELUM_PEMBARUAN')),
	CONSTRAINT "chk_cadangan_tujuan" CHECK ((status_lokal is null or status_lokal in ('BERHASIL','GAGAL','NONAKTIF'))
        and (status_cloud is null or status_cloud in ('BERHASIL','GAGAL','NONAKTIF')))
);
